"""Generate bilingual, sketch-specific customer tutorials with synchronized code."""
from pathlib import Path
import re

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/robocore-wiki'
oled='Adafruit SSD1306 2.5.17; Adafruit GFX Library 1.12.6; Adafruit BusIO'
jsonlib='ArduinoJson 7.4.3 (Benoit Blanchon)'
# title, required hardware, dependencies, operation and troubleshooting in both languages.
data={}
for family,center in [('SCS',511),('HLS',2047),('STS',2047),('SMS',2047)]:
    data[family+'_Servo']=(f'{family} 总线舵机',f'{family} bus servo',
      f'一只 {family} 舵机，ID=1、总线波特率 1000000。断电后按舵机物理协议接 5264-3P TTL 或 XH2.54-4P RS485，主控 RX5/TX4。XT30 输入电压必须符合该舵机额定值。',
      f'One {family} servo with ID 1 and bus baud 1000000. With power off, use 5264-3P TTL or XH2.54-4P RS485 to match the servo interface, controller RX5/TX4. XT30 voltage must match its rating.',
      'FTServo 2.0.0 (ftservo / FEETECH)',
      f'先发送 `r` 读取位置、速度。核对 `ID` 和 `CENTER={center}`，保证中位及中位 + 50 计数均在机械行程内。发送 `m` 会使能并移动到 **CENTER + 50 的绝对位置**，不是在当前位置增加 50；`c` 移动到 CENTER；`x` 关闭扭矩。关闭扭矩后负载可能自由下落，请先支撑。'+(' HLS 的 WritePosEx 最后一个参数 150 是电流限制寄存器值，请按设备规格设置。' if family=='HLS' else ''),
      f'Send `r` to read position and speed. Check `ID` and `CENTER={center}` against mechanical travel. `m` enables torque and moves to **absolute CENTER + 50**, not 50 counts from the current position. `c` moves to CENTER; `x` disables torque. Support the load before disabling torque.'+(' The final WritePosEx argument, 150, is a current-limit register value; configure it for the servo.' if family=='HLS' else ''),
      '读数为负数或无响应时，检查 ID、波特率、动力电源和协议型号。不要用另一个型号的行程参数测试。',
      'Negative readings or no reply: check ID, baud, motor power and protocol family. Do not reuse another model’s travel limits.')
data.update({
'Bus_Scan':('总线 ID 扫描','Bus ID scan','一个支持协议的 TTL/RS485 设备，接 IO4 TX / IO5 RX 对应总线接口；设备单独获得额定动力供电。','One compatible TTL/RS485 device on the IO4 TX / IO5 RX bus, with rated external power.','bundled:lygion_devs','发送 `s`，程序依次 Ping 0–253，打印 `ID n`，最后打印 `Scan finished`。结果只说明该 ID 有响应，不会自动识别产品型号。默认波特率 1000000；设备若使用其它波特率，修改 Serial1.begin 的第一个参数。','Send `s` to ping IDs 0–253. Each response prints `ID n`, followed by `Scan finished`. This finds responding IDs, not product types. Default baud is 1000000; edit the first Serial1.begin argument to match other devices.','无设备时检查动力电源、共地、线序及波特率。两个相同 ID 可能冲突，逐个接入修改 ID。','If empty, check power, ground, wiring and baud. Duplicate IDs can collide; connect devices individually to change IDs.'),
'TTL_Node':('TTL Node：PWM、RGB 与 S.BUS','TTL Node: PWM, RGB and S.BUS','TTL Node (A)，默认 ID=1，1000000 baud，连接 5264-3P 总线。测试 S.BUS 时连接匹配的接收机。','TTL Node (A), ID 1 at 1000000 baud on the 5264-3P bus. Add a compatible receiver for S.BUS.','bundled:lygion_devs','`p` 将 PWM 通道 1 设为 100/1000（10%），`x` 归零；`l` 设置两组状态灯；`s` 读取 16 个通道和 S.BUS 状态字节。`i` 把 ID 1 改为 2，只接目标设备且确认 ID 2 空闲。成功后本次运行自动使用 ID 2；重启程序前也要将变量 id 改为 2。','`p` sets PWM channel 1 to 100/1000 (10%); `x` sets zero. `l` sets both indicators; `s` prints 16 channels and S.BUS status. `i` changes ID 1 to 2: connect only the target and ensure ID 2 is free. After success this session uses ID 2; also change variable id to 2 before restarting the sketch.','S.BUS 寄存器回复不等于无线接收正常，还要查看状态字节和通道变化。RGB 使用 SDK 量化色值，不是通用 0–255 色值。','A register reply does not guarantee radio reception: check status and changing channels. RGB uses SDK quantized values, not general 0–255 colors.'),
'TTL_Stepper':('TTL 步进驱动','TTL stepper driver','TTL Stepper Driver (A)、匹配步进电机及额定电源。默认 ID=1、1000000 baud，TTL 总线连接 IO4/IO5。先确认驱动器相位、电流配置和机械空间。','TTL Stepper Driver (A), matching motor and rated supply. Default ID 1, 1000000 baud on IO4/IO5 TTL. Check phase/current configuration and mechanical clearance.','bundled:lygion_devs','先 `r` 读反馈。位置模式：`0` → `e` → `p`，目标为绝对位置 3200。连续模式：`1` → `e` → `v`，`s` 将连续速度归零；`x` 失能。模式修改会关闭输出，模式 0/1 切换无需重启。`z` 将当前位置坐标设为 0，不产生运动。`2` 为从动模式，示例从 ID=2，需按设备教程连接 EDS 并保持主 ID 唯一。','Read with `r` first. Position mode: `0` → `e` → `p`, targeting absolute position 3200. Speed mode: `1` → `e` → `v`; `s` sets speed to zero, `x` disables output. Mode writes disable output; switching 0/1 needs no restart. `z` assigns zero to the current position without moving. `2` selects follower mode with leader ID 2; wire EDS as documented and keep primary IDs unique.','CURRENT=150、速度100、加速度10 都是寄存器值，不能按安培或普通步/秒理解。只改相位配置才需要重启。模式不对时不要发送对应运动指令。','CURRENT=150, speed 100 and acceleration 10 are register values, not amperes or ordinary steps/s. Phase changes require restart. Match each movement command to its operating mode.'),
'TTL_Encoder':('TTL 编码器 E02','TTL Encoder E02','TTL Encoder E02，ID=1、1000000 baud，通过 TTL 接口连接 IO4/IO5；手动转动轴用于观察反馈。','TTL Encoder E02, ID 1 at 1000000 baud on IO4/IO5 TTL; rotate its shaft by hand to inspect feedback.','bundled:lygion_devs','发送 `r`，读取位置、角度及速度。每圈 4096 计数，示例角度=位置×360/4096，包含多圈累积。需要校准时发送 `z`，把当前位置设为 0；校准会保存，请勿在循环里高频调用。','Send `r` for position, angle and speed. There are 4096 counts per turn; displayed angle = position × 360/4096 and includes accumulated turns. Send `z` only when calibration is needed to assign zero to the current position; calibration is persistent, so do not call it repeatedly.','位置范围为 0–65534；基准校准保存，但多圈累积不在断电后保留。读取失败先查 ID、波特率和供电，不要把错误当角度。','Position range is 0–65534. The calibration reference persists, but accumulated turns do not survive power loss. Check ID, baud and power on read failure; never use errors as angles.'),
'CAN_Communication':('CAN 外部通信','External CAN communication','开关拨至 CAN，通过 CAN 2+2 连接另一个 500 kbps CAN 节点，CAN H/L 对应且共地；RX13/TX14。板载 120Ω 终端，按总线两端的实际终端配置组网。','Set selector to CAN. Connect another 500 kbps node through CAN 2+2, matching H/L and common ground; RX13/TX14. Account for onboard 120Ω termination when arranging the two bus ends.','core:driver/twai.h','发送 `t`，发出标准帧 ID=0x100，数据 0x12 0x34；查看 Transmit result。对端向本板发送帧时，串口打印 CAN ID、DLC 和每个数据字节。发送接口返回成功只表示帧进入发送流程，最终接收需对端确认。','Send `t` to transmit standard ID 0x100 with bytes 0x12 0x34 and inspect Transmit result. Incoming peer frames print CAN ID, DLC and payload bytes. A successful transmit call means submission, not confirmed application receipt; verify at the peer.','无法发送时检查开关、双方波特率、H/L、共地、终端及有效应答节点；不要把 IO13/14 直接当 CAN H/L 接线。','If transmission fails, check selector, baud, H/L, ground, termination and an active acknowledging peer. GPIO13/14 are not CAN H/L terminals.'),
'RS485_Communication':('外部 RS485 通信','External RS485 communication','开关拨至 485，通过 GH1.25-5P 连接 RS485 对端的 A/B/GND，115200、8N1；使用 UART2 RX13/TX14。对端自行供电时不并联两个电源输出。','Set selector to 485; connect GH1.25-5P A/B/GND to an RS485 peer at 115200, 8N1. Uses UART2 RX13/TX14. Do not parallel power outputs when the peer is separately powered.','core:HardwareSerial','发送 `t`，主板发送一行 `RoboCore S3 RS485` 加换行；对端应收到对应文本。对端发送字节后本板以十六进制打印。双方轮流发送以避免半双工冲突，板上自动切换收发方向，无需 DE 引脚。','Send `t` to transmit `RoboCore S3 RS485` plus newline; verify that text at the peer. Received bytes print in hexadecimal. Take turns transmitting to avoid half-duplex collisions. Onboard direction control requires no DE pin.','这是字节收发例程，不是出厂 JSON 网关，也不是 IO4/IO5 的舵机 RS485。乱码先检查波特率、8N1、A/B 线序及共地。','This is a byte transport demo, not the factory JSON gateway or the IO4/IO5 servo RS485 bus. For corrupt data check baud, 8N1, A/B and ground.'),
'OLED':('外接 OLED 显示','External OLED display','User Interface Module (A) 或兼容 SSD1306 128×32 I²C OLED。SDA6、SCL7，地址 0x3C；使用适合模块的供电和 3.3V GPIO 电平。','User Interface Module (A) or compatible SSD1306 128×32 I²C OLED, SDA6/SCL7, address 0x3C; use correct module power and 3.3V GPIO levels.',oled,'上传后屏幕每 500ms 更新一次 RoboCore S3 和运行秒数。修改 screen.println 的 ASCII 文本可显示自己的消息。默认字体不支持直接显示中文汉字。','After upload, the display updates RoboCore S3 and uptime every 500 ms. Change ASCII screen.println text for your own message. The default font cannot directly render Chinese characters.','出现 OLED absent 时检查模块是否接入、0x3C 地址、线序和屏幕型号。板载惯性传感器也使用 Wire；合并程序时只初始化一次总线。','If OLED absent appears, check connection, address 0x3C, wiring and display model. The onboard IMU shares Wire; initialize the bus once when combining sketches.'),
'User_Interface_Module_A':('User Interface Module (A)：按键、蜂鸣器和屏幕','User Interface Module (A): keys, buzzer and display','断电后将 UI Module (A) 接到 PH1.25-10P。上/下/左/右/确认=IO10/11/12/9/2，低有效；蜂鸣器21；OLED SDA6/SCL7、0x3C、128×32。这些资源都在外接模块上。','Connect UI Module (A) to PH1.25-10P with power off. Up/Down/Left/Right/OK use GPIO10/11/12/9/2, active low; buzzer21; OLED SDA6/SCL7, 0x3C, 128×32. All these resources are on the external module.',oled,'依次按五个按键，串口显示 Button: UP/DOWN/LEFT/RIGHT/OK，屏幕更新 Last，蜂鸣器响 80ms。去抖时间30ms；长按只触发一次，释放后再次按下才产生新事件。本例程不发送电机命令。','Press each key: serial prints Button: UP/DOWN/LEFT/RIGHT/OK, the OLED updates Last, and the buzzer sounds for 80 ms. Debounce is 30 ms; holding a key emits once until released and pressed again. This sketch sends no motor commands.','OLED 不可用时，按键和蜂鸣器继续工作。若按键无响应，检查模块方向、共地和 GPIO；不要把 RESET/BOOT 当作模块五向按键。','Buttons and buzzer continue if OLED is unavailable. Check module orientation, ground and GPIO if keys fail; RESET/BOOT are not the module’s five keys.'),
'QMI8658A':('板载惯性传感器 QMI8658A', 'Onboard QMI8658A IMU', 'RoboCore S3 板载 QMI8658A，无需外接 TTL IMU。I²C SDA6/SCL7，共用 OLED 总线，自动探测0x6A/0x6B。', 'RoboCore S3 onboard QMI8658A; no external TTL IMU required. I²C SDA6/SCL7 shares the OLED bus and probes 0x6A/0x6B.', 'core:Arduino.h / Wire.h', '例程每约 2 ms 检查新样本，每 200 ms 输出一次串口数据；串口显示频率不是传感器采样率。传感器输出率为 112.1 Hz，量程为 ±8 g、±512°/s。a[g]、gyro[dps]、T[C] 分别表示三轴加速度、角速度和温度，count 为 24 位循环样本计数。静止时加速度合量约为 1 g，旋转时观察角速度变化。输出为原始测量值，不包含姿态融合。', 'The sketch checks for a new sample about every 2 ms and prints every 200 ms; display rate is separate from sensor sampling. The sensor output rate is 112.1 Hz with ranges of ±8 g and ±512°/s. a[g], gyro[dps] and T[C] are acceleration, angular velocity and temperature; count is a wrapping 24-bit sample counter. At rest acceleration magnitude is about 1 g; rotate the board to observe angular velocity. These are measurements without attitude fusion.', '出现初始化失败或超过 100 ms 无新数据的提示时，检查供电，并断电检查共享 I²C 外设接线。无需安装第三方 QMI 库。二次开发可在 readImu(sample) 返回 true 时处理新样本，将 PRINT_IMU 设为 false 可关闭串口周期输出。', 'If initialization fails or no fresh data arrives for 100 ms, check power and inspect shared I²C wiring with power disconnected. No third-party QMI library is required. Process new samples when readImu(sample) returns true; set PRINT_IMU to false to disable periodic serial output.'),
'HTTP_JSON':('HTTP JSON 通信','HTTP JSON communication','带 Wi-Fi 的电脑，连接外部天线后再运行。此例只读写内存数值，不控制电机。','A Wi-Fi computer; attach the external antenna before running. This sketch only reads/writes a RAM value and does not control motors.',jsonlib,'电脑连接热点 RoboCoreDemo，密码12345678。用 POST 向 http://192.168.4.1/api/cmd 发送 {"T":1,"value":42}，得到 {"ok":true,"value":42}；再发送 {"T":2} 读取。同一数值在重启后归零。使用下方 PowerShell 请求示例；浏览器地址栏的 GET 不是 POST。','Connect to RoboCoreDemo with password12345678. POST {"T":1,"value":42} to http://192.168.4.1/api/cmd for {"ok":true,"value":42}; send {"T":2} to read. Value resets on reboot. Use the PowerShell example below; typing the address in a browser sends GET, not POST.','HTTP400 表示非法或超过255字节的输入。没有网页首页属于正常现象；此单元例程只提供 API，完整控制台需恢复完整固件。','HTTP400 indicates invalid or oversized input (over255 bytes). No home page is expected: this sketch exposes only an API; restore full firmware for the console.'),
'WebSocket_JSON':('WebSocket JSON 通信','WebSocket JSON communication','带 Wi-Fi 的电脑及 WebSocket 客户端，先连接外部天线。','Wi-Fi computer and a WebSocket client; attach the external antenna first.',jsonlib+'; AsyncTCP 3.5.0 (ESP32Async); ESPAsyncWebServer 3.12.1 (ESP32Async)','连接热点 RoboCoreDemo / 12345678，客户端打开 ws://192.168.4.1/ws。发送单个文本帧 {"T":1,"value":42}，再发送 {"T":2}，均收到 ok/value。可用下方 Python 客户端。','Connect to RoboCoreDemo / 12345678 and open ws://192.168.4.1/ws. Send one text frame {"T":1,"value":42}, then {"T":2}; replies contain ok/value. A Python client is shown below.','必须使用 ESP32Async 的两个库；不要混入旧分支。例程拒绝二进制帧、分片帧、超过255字节的文本。浏览器普通地址栏不能代替 WebSocket 客户端。','Use both libraries from ESP32Async, without mixing old forks. The sketch rejects binary, fragmented and over255-byte frames. An ordinary browser address bar is not a WebSocket client.'),
'USB_CDC_JSON':('原生 USB CDC JSON 通信','Native USB CDC JSON communication','USB 数据线连接 Type-C USB（IO19/20），选择 USB-OTG (TinyUSB) 和 USB CDC On Boot Enabled。','Connect a data cable to Type-C USB (GPIO19/20); select USB-OTG (TinyUSB) and USB CDC On Boot Enabled.',jsonlib,'串口监视器选择原生 USB 端口并启用换行，发送 {"T":1,"value":42}，随后 {"T":2}；回复 ok=true、value=42。连续读取回复，避免输出缓冲塞满。程序通过 USB EVENT 收包，每行最多255字节，等待队列只保留最新一条。','Select the native USB port and newline in Serial Monitor. Send {"T":1,"value":42}, then {"T":2}; replies contain ok=true,value=42. Keep reading replies to drain the output buffer. USB EVENT receives up to255 bytes per line; only the latest pending command is retained.','无回复先确认接的是 Type-C USB、已发送换行且 CDC 设置正确；不要同时用串口监视器和 Python 占用同一端口。该教学协议不支持完整固件的总线控制命令。','No reply: check Type-C USB, newline and CDC settings. Do not open the same port in Serial Monitor and Python simultaneously. This teaching protocol does not implement factory bus-control commands.'),
'ESP_NOW_JSON':('ESP-NOW 无线 JSON','ESP-NOW wireless JSON','两块 ESP32-S3 控制板，均连接外部天线；示例使用信道1，双方需一致。','Two ESP32-S3 controllers with external antennas connected; both use channel1.',jsonlib,'先上传并记录双方串口打印的 STA MAC，随后把各自 peerMac 数组改为对方地址并重新上传。发送端串口输入 s，接收端打印 {"T":603}。这只是展示数据帧，接收单元例程不会执行 T=603。发送返回0表示交给协议栈，不等于对端业务已执行。','Upload first to read each STA MAC, then set each peerMac array to the other board’s address and upload again. Enter s on the sender; the receiving sketch prints {"T":603}. This demonstrates a packet, not execution of T=603. Send result0 means stack submission, not confirmed application execution.','接收不到时检查 MAC、信道、天线和距离。对接完整固件时需在完整固件设置 T=410/411/414，并遵守250字节补零消息帧格式。','Check MAC, channel, antennas and range if nothing arrives. To communicate with full firmware, configure T=410/411/414 there and use its250-byte zero-padded JSON frame.'),
'RGB_Buzzer':('外接 RGB 与蜂鸣器（可选接线）','External RGB and buzzer (optional wiring)','本例需要另行接线的两颗 WS2812 灯（示例 GPIO26）及 UI Module (A) 的 GPIO21 蜂鸣器。RoboCore S3 无板载可寻址 RGB，GPIO26 未引出到 PH1.25-10P；使用 UI 模块的按键、屏幕和蜂鸣器时，请选择 User_Interface_Module_A。若改用扩展口空闲 GPIO，请先修改 leds 构造函数，且不能与已连接按键或总线共用。','Requires two separately wired WS2812 LEDs (example GPIO26) and the UI Module (A) GPIO21 buzzer. RoboCore S3 has no onboard addressable RGB; GPIO26 is not exposed on PH1.25-10P. Use User_Interface_Module_A for the module’s buttons, display and buzzer. To use a free expansion GPIO, edit the leds constructor and avoid pins occupied by connected keys or buses.','Adafruit NeoPixel 1.15.5 (Adafruit)','确认灯带供电、逻辑电平和共地后，输入 l 显示蓝色，x 关闭灯；b 发出1500Hz、100ms短鸣。灯的亮度在代码中设为20。','After verifying LED power, logic levels and ground, enter l for blue, x for off, b for a1500 Hz,100 ms tone. LED brightness is set to20.','没有另外接灯时不会出现灯光，这是预期行为。不要向 GPIO 接入动力电压；只测试蜂鸣器时无需运行灯带操作。','No light is expected without external LEDs. Never apply motor-supply voltage to GPIO; use only the buzzer command when testing the buzzer alone.')})

common_zh='''## Arduino IDE 与开发板设置

1. 安装 Arduino IDE 2。打开 **文件 → 首选项 → 附加开发板管理器网址**，加入 `https://espressif.github.io/arduino-esp32/package_esp32_index.json`。
2. 打开 **工具 → 开发板 → 开发板管理器**，搜索 `esp32`，选择作者 **Espressif Systems** 的包，安装 **3.3.0**。
3. 在 **工具 → 开发板 → esp32** 选择 **ESP32S3 Dev Module**。设置 Flash Size=8MB、PSRAM=OPI PSRAM、USB Mode=USB-OTG (TinyUSB)、USB CDC On Boot=Enabled。串口输出使用原生 USB。
4. 下载并解压[例程包](../../../../assets/files/robocore-s3/examples.zip)，打开 `arduino_example/{name}/{name}.ino`，不要将多个例程合并到同一工程。

安装界面详见[安装 Arduino IDE](../../../../tutorials/install-arduino-ide.md)；开发板来源见 [Espressif 安装指南](https://docs.espressif.com/projects/arduino-esp32/en/latest/installing.html)。
'''
common_en='''## Arduino IDE and board settings

1. Install Arduino IDE 2. In **File → Preferences → Additional Boards Manager URLs**, add `https://espressif.github.io/arduino-esp32/package_esp32_index.json`.
2. Open **Tools → Board → Boards Manager**, search `esp32`, and install **3.3.0** of the package by **Espressif Systems**.
3. Select **Tools → Board → esp32 → ESP32S3 Dev Module**. Set Flash Size=8MB, PSRAM=OPI PSRAM, USB Mode=USB-OTG (TinyUSB), USB CDC On Boot=Enabled. Serial output uses native USB.
4. Extract the [example archive](../../../../assets/files/robocore-s3/examples.zip) and open `arduino_example/{name}/{name}.ino`. Keep each sketch in its own project.

See [Arduino IDE installation](../../../../tutorials/install-arduino-ide.md) and the [Espressif installation guide](https://docs.espressif.com/projects/arduino-esp32/en/latest/installing.html).
'''
for name,entry in data.items():
    for lang in ('zh','en'):
        zh=lang=='zh'; title=entry[0 if zh else 1];hardware=entry[2 if zh else 3];deps=entry[4];ops=entry[5 if zh else 6];trouble=entry[7 if zh else 8]
        if deps.startswith('bundled:'):
            lib=deps.split(':')[1]
            dependency=(f'本例只需例程包自带的 **{lib}**；不用在库管理器搜索同名第三方库。打开“文件 → 首选项”查看 Sketchbook location（项目文件夹位置），把包内 `lib/{lib}` 整个目录复制为 `<Sketchbook>/libraries/{lib}`，确认其下直接包含 `library.properties` 和 `src`，然后重启 IDE。不要多套一层目录。' if zh else f'This sketch needs the included **{lib}**, not a similarly named third-party package. Find Sketchbook location in File → Preferences, copy the entire `lib/{lib}` folder to `<Sketchbook>/libraries/{lib}`, with `library.properties` and `src` directly inside, then restart the IDE. Avoid an extra nested folder.')
        elif deps.startswith('core:'):
            dependency=(f'无需安装额外库。`{deps.split(":")[1]}` 随上面的 esp32 开发板包提供。找不到头文件时，请检查是否安装并选择了 ESP32S3，而不是安装其它同名库。' if zh else f'No additional library is needed. `{deps.split(":")[1]}` comes with the esp32 board package. If a header is missing, verify the selected ESP32S3 board and installed core instead of adding an unrelated library.')
        else:
            dependency=('打开 **工具 → 管理库**，逐项搜索并安装下列库（版本下拉框可选择指定版本），核对作者；如提示依赖安装，选择 Install all。\n\n' if zh else 'Open **Tools → Manage Libraries**, search and install each package below, choose the listed version and verify the author. Choose Install all when dependency installation is offered.\n\n')+'\n'.join('- '+d.strip() for d in deps.split(';'))+'\n\n'+('[Arduino 库安装说明](https://support.arduino.cc/hc/en-us/articles/5145457742236-Install-libraries-in-the-Arduino-IDE)。' if zh else '[Arduino library installation guide](https://support.arduino.cc/hc/en-us/articles/5145457742236-Install-libraries-in-the-Arduino-IDE).')
        code=(ROOT/f'arduino_example/{name}/{name}.ino').read_text(encoding='utf-8')
        # Keep executable code identical while adding useful Chinese teaching comments.
        if zh:
            code='// RoboCore S3：'+title+'\n// 上传此独立例程后，原来的完整网页固件将被替换。\n'+code
            code=code.replace('void setup() {','// 上电执行一次：初始化所需通信接口和设备。\nvoid setup() {').replace('void loop() {','// 循环执行：按本页操作步骤触发功能并观察反馈。\nvoid loop() {')
            code=code.replace('Serial.begin(115200);','Serial.begin(115200); // 串口监视器，原生 USB CDC').replace('Serial1.begin(1000000, SERIAL_8N1, 5, 4);','Serial1.begin(1000000, SERIAL_8N1, 5, 4); // 舵机/TTL 总线：RX5、TX4')
        text=f'# {title}\n\n'+('**这是独立单元例程。上传会替换完整网页固件；需要恢复控制台时使用[固件恢复](../firmware.md)。**\n\n## 准备硬件与接线\n\n' if zh else '**This is a standalone sketch. Uploading replaces the complete web firmware; use [firmware recovery](../firmware.md) to restore the console.**\n\n## Hardware and wiring\n\n')+hardware+'\n\n'+(common_zh if zh else common_en).format(name=name)+'\n'+('## 本例依赖\n\n' if zh else '## Libraries for this sketch\n\n')+dependency+'\n\n'+('## 编译与上传\n\n1. 点击“验证”编译，确认没有错误。缺少 `.h` 文件时按上节安装对应库，再重新编译。\n2. Type-C UART 支持自动下载；若用 Type-C USB，按住 BOOT，按下并松开 RESET，再松开 BOOT，选择出现的端口后上传。\n3. 上传完成按 RESET 运行。使用 Type-C UART 下载时，将数据线切到 Type-C USB 观察本例的 Serial 输出；选择重新枚举的端口。打开串口监视器，115200。若错过启动提示，保持监视器打开再按 RESET。\n\n## 操作与预期结果\n\n' if zh else '## Compile and upload\n\n1. Click Verify and resolve compilation errors. If a `.h` file is missing, install the dependency listed above and compile again.\n2. Type-C UART supports automatic download. For Type-C USB, hold BOOT, press/release RESET, release BOOT, select the new port and upload.\n3. Press RESET to run. If you uploaded over Type-C UART, move the data cable to Type-C USB for this sketch’s Serial output and select the re-enumerated port. Open Serial Monitor at115200. Reset with the monitor open if you missed startup messages.\n\n## Operation and expected results\n\n')+ops+'\n\n'+('## 排查与下一步\n\n' if zh else '## Troubleshooting and next steps\n\n')+trouble+'\n\n'+('接口和电压详见[硬件说明](../hardware.md)，完整固件命令见[JSON 指令集](../json-api.md)。\n\n## 完整代码\n\n' if zh else 'See [hardware](../hardware.md) for interfaces and voltage, and the [JSON reference](../json-api.md) for full-firmware commands.\n\n## Complete code\n\n')+'```cpp\n'+code.rstrip()+'\n```\n'
        if name != 'USB_CDC_JSON':
            text=text.replace('USB CDC On Boot=Enabled。串口输出使用原生 USB。', 'USB CDC On Boot=Disabled。反馈和交互输入使用 Serial0（UART0），连接 Type-C UART。')
            text=text.replace('USB CDC On Boot=Enabled. Serial output uses native USB.', 'USB CDC On Boot=Disabled. Feedback and interactive input use Serial0 (UART0) through Type-C UART.')
            text=text.replace('使用 Type-C UART 下载时，将数据线切到 Type-C USB 观察本例的 Serial 输出；选择重新枚举的端口。', '数据线保持连接 Type-C UART，选择与上传相同的串口查看 Serial0 反馈，无需更换接口。')
            text=text.replace('If you uploaded over Type-C UART, move the data cable to Type-C USB for this sketch’s Serial output and select the re-enumerated port.', 'Keep the cable connected to Type-C UART and use the same port as uploading for Serial0 feedback; no cable change is needed.')
        if name=='HTTP_JSON': text+='\n### PowerShell\n\n```powershell\nInvoke-RestMethod -Uri http://192.168.4.1/api/cmd -Method Post -ContentType application/json -Body \'{"T":1,"value":42}\'\nInvoke-RestMethod -Uri http://192.168.4.1/api/cmd -Method Post -ContentType application/json -Body \'{"T":2}\'\n```\n'
        if name=='WebSocket_JSON': text+='\n### Python\n\n```shell\npython -m pip install websocket-client\n```\n\n```python\nimport websocket\nws = websocket.create_connection("ws://192.168.4.1/ws", timeout=5)\ntry:\n    ws.send(\'{"T":1,"value":42}\')\n    print(ws.recv())\n    ws.send(\'{"T":2}\')\n    print(ws.recv())\nfinally:\n    ws.close()\n```\n'
        folder=OUT/lang/'arduino';folder.mkdir(exist_ok=True)
        (folder/(name.lower().replace('_','-')+'.md')).write_text(text,encoding='utf-8')
for lang in ('zh','en'):
    zh=lang=='zh'
    intro=('# Arduino 单元例程\n\n每篇教程都包含接线、开发板安装、该例程的具体依赖、上传步骤、预期结果和完整代码。按功能选一篇开始；上传单元例程会替换网页固件，可随时按[固件恢复](firmware.md)刷回。\n\n' if zh else '# Arduino unit examples\n\nEach tutorial includes wiring, board installation, exact dependencies, upload steps, expected results and complete code. Choose one function to start. Uploading a unit sketch replaces the web firmware; restore it with [firmware recovery](firmware.md).\n\n')
    intro+=('| 教程 | 工程目录 |\n| --- | --- |\n' if zh else '| Tutorial | Sketch folder |\n| --- | --- |\n')
    for name,entry in data.items(): intro+=f'| [{entry[0 if zh else 1]}](arduino/{name.lower().replace("_","-")}.md) | `{name}` |\n'
